HMODULE g_hCdmGameServer = NULL;	// set by the project loader once GameServer.dll is loaded (for string-list plugins)

static ClassDef** g_ppCdm = NULL;
static int g_nCdm = 0;

// Returns a table of ClassDef pointers in the Jupiter layout (never freed; DEdit copies it).
ClassDef** Condemned_GetClassDefs(int* pnClasses)
{
	if(!g_ppCdm)
	{
		g_nCdm = (int)(sizeof(g_Classes) / sizeof(g_Classes[0]));
		g_ppCdm = (ClassDef**)malloc(sizeof(ClassDef*) * g_nCdm);
		for(int i = 0; i < g_nCdm; i++)
		{
			ClassDef* pC = (ClassDef*)calloc(1, sizeof(ClassDef));
			pC->m_ClassName = (char*)g_Classes[i].name;
			pC->m_ClassFlags = g_Classes[i].flags;
			pC->m_nProps = (short)g_Classes[i].n;
			pC->m_Props = (PropDef*)calloc(g_Classes[i].n ? g_Classes[i].n : 1, sizeof(PropDef));
			for(int j = 0; j < g_Classes[i].n; j++)
			{
				const CdmProp& cp = g_Classes[i].p[j];
				PropDef* pd = &pC->m_Props[j];
				pd->m_PropName = (char*)cp.name;
				pd->m_PropType = cp.type;
				pd->m_DefaultValueVector = LTVector(cp.x, cp.y, cp.z);
				pd->m_DefaultValueFloat = cp.f;
				pd->m_DefaultValueString = (char*)cp.s;
				pd->m_PropFlags = cp.flags;
			}
			g_ppCdm[i] = pC;
		}
		// parents (by name; the table lists parents first)
		for(int i = 0; i < g_nCdm; i++)
		{
			g_ppCdm[i]->m_ParentClass = NULL;
			if(g_Classes[i].parent[0])
				for(int k = 0; k < g_nCdm; k++)
					if(strcmp(g_Classes[k].name, g_Classes[i].parent) == 0) { g_ppCdm[i]->m_ParentClass = g_ppCdm[k]; break; }
		}
	}
	// Property drop-down lists come from the game's own plugin code, once its DLL is loaded.
	for(int i = 0; i < g_nCdm; i++)
		g_ppCdm[i]->m_PluginFn = (0 && g_hCdmGameServer && g_Classes[i].pluginRva)
			? (CreateObjectPluginFn)((BYTE*)g_hCdmGameServer + g_Classes[i].pluginRva) : NULL;
	*pnClasses = g_nCdm;
	return g_ppCdm;
}

