const char* const* Condemned_GetPropList(const char* pProp, int* pn)
{
	for(int i = 0; i < (int)(sizeof(g_CdmLists) / sizeof(g_CdmLists[0])); i++)
		if(strcmp(g_CdmLists[i].prop, pProp) == 0) { *pn = g_CdmLists[i].n; return g_CdmLists[i].s; }
	*pn = 0;
	return 0;
}
